            {"metric": "CPU L1 캐시→드라이버 내부 버퍼 복사 시간(설명값)", "value": "2E+1", "value_kind": "scalar", "unit": "ns", "condition": "No-Pin, 1,028 Byte", "element_ids": ["p77:e600", "p77:enh:e6"]},
